// ─── CIRCUIT WTA ──────────────────────────────────────────────────────────────
// Calendrier féminin calqué sur la vraie saison (noms proches mais pas
// identiques). Mêmes catégories internes que le circuit masculin, donc même
// barème de points et mêmes formats de tableau :
//   GrandSlam = Majeur · Masters1000 = WTA 1000 · ATP500 = WTA 500
//   ATP250 = WTA 250 · Challenger = WTA 125 et ITF W75/W100 · ITF = W15/W35
// Les Majeurs, Indian Wells, Miami, Madrid, Rome et Cincinnati sont
// communs aux deux circuits ; les ITF reprennent la liste masculine.
export const WTA_SHARED_IDS = new Set(["ao", "rg", "wimbledon", "uso", "indian_wells", "miami", "madrid", "rome", "cincinnati"]);
export const wt = (id, name, surface, tier, city, week) => {
  const base = {
    Masters1000: { prize: 80000, points: 1000, entryFee: 0 },
    ATP500:      { prize: 30000, points: 500,  entryFee: 0 },
    ATP250:      { prize: 12000, points: 250,  entryFee: 0 },
    WTA125:      { prize: 3500,  points: 125,  entryFee: 30 },
    W100:        { prize: 3000,  points: 100,  entryFee: 30 },
  }[tier];
  const realTier = tier === "WTA125" || tier === "W100" ? "Challenger" : tier;
  return { id, name, surface, prize: base.prize, points: base.points, tier: realTier, city, week, entryFee: base.entryFee };
};
